css:
@import url('https://fonts.googleapis.com/css2?family=Special+Elite&family=Permanent+Marker&family=Courier+Prime:ital,wght@0,400;0,700;1,400&display=swap');

:root {
  --bg: #0a0008;
  --ink: #e8ddf0;
  --mid: #9b7ab0;
  --border: #2a1a30;
  --accent: #c94fa8;
  --font: 'Courier Prime', monospace;
  --pad-x: 0px;
  --pad-top: 0px;
}

* {
  box-sizing: border-box;
}

body {
  background: var(--bg);
  background-image:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 2px,
      rgba(180, 80, 180, 0.015) 2px,
      rgba(180, 80, 180, 0.015) 4px
    ),
    radial-gradient(ellipse at 20% 10%, rgba(120, 0, 80, 0.18) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 80%, rgba(60, 0, 120, 0.22) 0%, transparent 60%);
  min-height: 100vh;
}

/* ===== INTRO ===== */
.intro {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 60px 48px 40px;
  position: relative;
  border-bottom: 1px solid #2a1a30;
}

.intro::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 3px;
  height: 100%;
  background: linear-gradient(to bottom, #c94fa8, transparent, #5c1a8e);
}

.intro::after {
  content: '✦ nobody understands me ✦';
  position: absolute;
  bottom: 16px;
  right: 32px;
  font-family: 'Courier Prime', monospace;
  font-size: 10px;
  color: #4a2a5a;
  letter-spacing: 0.2em;
  text-transform: lowercase;
}

.intro-left {
  width: 100%;
  margin-bottom: 32px;
}

.intro-headline {
  font-family: 'Permanent Marker', cursive;
  font-size: clamp(2.8rem, 8vw, 6rem);
  color: var(--ink);
  line-height: 0.95;
  letter-spacing: -0.02em;
  text-shadow:
    2px 2px 0 #c94fa8,
    4px 4px 0 rgba(90, 0, 60, 0.4);
  transform: rotate(-1.5deg);
  display: inline-block;
  position: relative;
}

.intro-headline::after {
  content: '';
  display: block;
  width: 60%;
  height: 2px;
  background: linear-gradient(to right, #c94fa8, transparent);
  margin-top: 12px;
  transform: rotate(0.5deg);
}

.intro-right {
  width: 100%;
  max-width: 600px;
  padding-left: 24px;
  border-left: 2px solid #3a1a4a;
  position: relative;
}

.intro-right::before {
  content: '//';
  position: absolute;
  left: -18px;
  top: 0;
  color: #c94fa8;
  font-family: 'Courier Prime', monospace;
  font-size: 1.2rem;
  opacity: 0.6;
}

.bio-text {
  font-family: 'Courier Prime', monospace;
  font-size: 0.92rem;
  color: #b09ac0;
  line-height: 1.9;
  margin-bottom: 14px;
  font-style: italic;
}

.contact-line {
  font-family: 'Courier Prime', monospace;
  font-size: 0.85rem;
  color: var(--mid);
  letter-spacing: 0.1em;
}

.contact-trigger {
  color: #c94fa8 !important;
  text-decoration: none;
  border-bottom: 1px dashed #c94fa8;
  font-style: italic;
  transition: color 0.2s, text-shadow 0.2s;
}

.contact-trigger:hover {
  color: #e87fd0 !important;
  text-shadow: 0 0 12px rgba(201, 79, 168, 0.6);
}

/* ===== SECTION LABEL ===== */
.section-label {
  font-family: 'Courier Prime', monospace;
  font-size: 0.65rem;
  color: #5a3a6a;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  padding: 32px 48px 16px;
  position: relative;
}

.section-label::before {
  content: '— ';
  color: #c94fa8;
  opacity: 0.5;
}

/* ===== WORK SECTION ===== */
.work-section {
  padding: 0 0 80px;
}

.work-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.work-item {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: stretch;
  border-top: 1px solid #1e0e28;
  padding: 0;
  position: relative;
  transition: background 0.3s;
  overflow: hidden;
}

.work-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 0;
  background: linear-gradient(to right, rgba(201, 79, 168, 0.04), transparent);
  transition: width 0.5s ease;
  pointer-events: none;
  z-index: 0;
}

.work-item:hover::before {
  width: 100%;
}

.work-item:nth-child(even) {
  flex-direction: row-reverse;
}

.work-item:nth-child(even) .work-image {
  order: -1;
}

.work-item-text {
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  z-index: 1;
}

.work-title {
  font-family: 'Permanent Marker', cursive;
  font-size: 1.8rem;
  color: var(--ink);
  margin-bottom: 12px;
  line-height: 1.1;
  display: inline-block;
  position: relative;
}

.work-title::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, #c94fa8, transparent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s ease;
}

.work-item:hover .work-title::after {
  transform: scaleX(1);
}

.work-desc {
  font-family: 'Courier Prime', monospace;
  font-size: 0.88rem;
  color: #9080a8;
  line-height: 1.8;
  font-style: italic;
  margin-bottom: 20px;
}

.work-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 8px;
}

.tag {
  font-family: 'Courier Prime', monospace;
  font-size: 0.68rem;
  color: #7a5a8a;
  border: 1px solid #3a1a4a;
  padding: 3px 10px;
  border-radius: 0;
  letter-spacing: 0.15em;
  text-transform: lowercase;
  background: transparent;
  transition: border-color 0.2s, color 0.2s;
}

.tag:hover {
  border-color: #c94fa8;
  color: #c94fa8;
}

.work-image {
  aspect-ratio: unset;
  min-height: 280px;
  overflow: hidden;
  position: relative;
  z-index: 1;
}

.work-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: grayscale(30%) contrast(1.1) saturate(0.7);
  mix-blend-mode: luminosity;
  transition: filter 0.5s, transform 0.6s;
  display: block;
}

.work-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(120, 0, 80, 0.35), rgba(40, 0, 80, 0.5));
  mix-blend-mode: multiply;
  pointer-events: none;
}

.work-item:hover .work-image img {
  filter: grayscale(10%) contrast(1.15) saturate(0.9);
  mix-blend-mode: normal;
  transform: scale(1.03);
}

.work-item-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 24px;
}

.work-item-footer a {
  font-family: 'Courier Prime', monospace;
  font-size: 0.78rem;
  color: #c94fa8;
  text-decoration: none;
  letter-spacing: 0.15em;
  text-transform: lowercase;
  transition: opacity 0.2s;
}

.work-item-footer a:hover {
  opacity: 0.7;
  text-decoration: underline;
  text-decoration-style: wavy;
}

/* ===== FOOTER ===== */
footer {
  padding: 64px 48px;
  border-top: 1px solid #2a1a30;
  background: #060005;
  position: relative;
  overflow: hidden;
}

footer::before {
  content: '♥ feel everything or feel nothing ♥';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: 'Permanent Marker', cursive;
  font-size: clamp(1.5rem, 4vw, 3rem);
  color: rgba(201, 79, 168, 0.06);
  white-space: nowrap;
  pointer-events: none;
  letter-spacing: 0.05em;
}

footer::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(to right, transparent, #c94fa8, transparent);
  opacity: 0.4;
}

.footer-nav {
  display: flex;
  gap: 32px;
  align-items: center;
  position: relative;
  z-index: 1;
}

.footer-nav a {
  font-family: 'Courier Prime', monospace;
  font-size: 0.75rem;
  color: #5a3a6a;
  text-decoration: none;
  letter-spacing: 0.3em;
  text-transform: lowercase;
  transition: color 0.2s, text-shadow 0.2s;
  position: relative;
}

.footer-nav a::before {
  content: '//';
  margin-right: 4px;
  opacity: 0.4;
  color: #c94fa8;
}

.footer-nav a:hover {
  color: #c94fa8;
  text-shadow: 0 0 16px rgba(201, 79, 168, 0.5);
}

/* ===== POPUP ===== */
.popup-overlay {
  background: rgba(5, 0, 10, 0.88);
  backdrop-filter: blur(6px);
}

.popup-card {
  position: fixed !important;
  top: 50% !important;
  left: 50% !important;
  right: auto !important;
  transform: translate(-50%, -50%) !important;
  width: min(520px, 90vw) !important;
  background: #0d0012;
  border: 1px solid #3a1a4a;
  border-radius: 0;
  padding: 48px;
  box-shadow:
    0 0 0 1px #1a0a22,
    0 0 60px rgba(201, 79, 168, 0.15),
    inset 0 0 40px rgba(80, 0, 60, 0.1);
  overflow: hidden;
}

.popup-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(to right, #5c1a8e, #c94fa8, #5c1a8e);
}

.popup-card::after {
  content: '✦';
  position: absolute;
  bottom: 16px;
  right: 20px;
  color: #2a1a30;
  font-size: 1.5rem;
  pointer-events: none;
}

.popup-title {
  font-family: 'Permanent Marker', cursive;
  font-size: 2rem;
  color: var(--ink);
  margin-bottom: 8px;
  text-shadow: 1px 1px 0 #c94fa8;
  transform: rotate(-0.5deg);
  display: inline-block;
}

.popup-sub {
  font-family: 'Courier Prime', monospace;
  font-size: 0.82rem;
  color: #7a5a8a;
  font-style: italic;
  margin-bottom: 32px;
  letter-spacing: 0.05em;
}

.popup-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.popup-form input,
.popup-form textarea {
  background: #080010;
  border: 1px solid #2a1a3a;
  border-radius: 0;
  color: #c8b8d8;
  font-family: 'Courier Prime', monospace;
  font-size: 0.88rem;
  padding: 12px 16px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  resize: vertical;
}

.popup-form input::placeholder,
.popup-form textarea::placeholder {
  color: #3a2a4a;
  font-style: italic;
}

.popup-form input:focus,
.popup-form textarea:focus {
  border-color: #c94fa8;
  box-shadow: 0 0 12px rgba(201, 79, 168, 0.15);
}

.popup-actions {
  display: flex;
  gap: 16px;
  margin-top: 8px;
  align-items: center;
}

.btn-submit {
  background: transparent;
  border: 1px solid #c94fa8;
  color: #c94fa8;
  font-family: 'Courier Prime', monospace;
  font-size: 0.8rem;
  letter-spacing: 0.25em;
  text-transform: lowercase;
  padding: 12px 28px;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, box-shadow 0.2s;
  border-radius: 0;
}

.btn-submit:hover {
  background: #c94fa8;
  color: #0a0008;
  box-shadow: 0 0 24px rgba(201, 79, 168, 0.4);
}

.btn-close {
  background: transparent;
  border: 1px solid #2a1a3a;
  color: #5a3a6a;
  font-family: 'Courier Prime', monospace;
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  text-transform: lowercase;
  padding: 12px 20px;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s;
  border-radius: 0;
}

.btn-close:hover {
  border-color: #5a3a6a;
  color: #9b7ab0;
}

/* ===== CASE STUDY ===== */
.top-nav {
  padding: 20px 48px;
  border-bottom: 1px solid #1e0e28;
  background: #060005;
}

.back-link {
  font-family: 'Courier Prime', monospace;
  font-size: 0.78rem;
  color: #7a5a8a;
  text-decoration: none;
  letter-spacing: 0.2em;
  transition: color 0.2s;
}

.back-link:hover {
  color: #c94fa8;
}

.back-link::before {
  content: '← ';
  color: #c94fa8;
}

.cs-title {
  font-family: 'Permanent Marker', cursive;
  font-size: clamp(2rem, 6vw, 4rem);
  color: var(--ink);
  text-shadow: 2px 2px 0 #c94fa8;
  transform: rotate(-0.8deg);
  display: inline-block;
}

.cs-header {
  padding: 48px;
  border-bottom: 1px solid #1e0e28;
}

.cs-section-label {
  font-family: 'Courier Prime', monospace;
  font-size: 0.65rem;
  color: #5a3a6a;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.cs-section-label::before {
  content: '// ';
  color: #c94fa8;
  opacity: 0.6;
}

.meta-label {
  font-family: 'Courier Prime', monospace;
  font-size: 0.68rem;
  color: #5a3a6a;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

.meta-value {
  font-family: 'Courier Prime', monospace;
  color: #b09ac0;
  font-style: italic;
}

.callout {
  border-left: 2px solid #c94fa8;
  background: rgba(201, 79, 168, 0.05);
  padding: 24px 32px;
  font-family: 'Courier Prime', monospace;
  font-style: italic;
  color: #c8b8d8;
  position: relative;
}

.callout::before {
  content: '\201C';
  position: absolute;
  top: -8px;
  left: 16px;
  font-size: 3rem;
  color: #c94fa8;
  opacity: 0.3;
  font-family: Georgia, serif;
  line-height: 1;
}

a {
  color: #c94fa8;
}

a:hover {
  color: #e87fd0;
}

::selection {
  background: #c94fa8;
  color: #0a0008;
}

::-webkit-scrollbar {
  width: 4px;
}

::-webkit-scrollbar-track {
  background: #0a0008;
}

::-webkit-scrollbar-thumb {
  background: #3a1a4a;
  border-radius: 0;
}

::-webkit-scrollbar-thumb:hover {
  background: #c94fa8;
}
